// ── Validate Claude's extraction output ───────────────────────
// Builder 1: update this after Claude Extract node is implemented.
// Expected: Claude returns JSON string inside content[0].text

const data = $input.first().json;

// Skip if marked (status updates, unsupported types)
if (data._skipExtraction) {
  return [{ json: { ...data, _valid: false, _reason: 'Extraction skipped' } }];
}

// Parse Claude response
let extracted = null;
try {
  // Claude returns: { content: [{ type: 'text', text: '{"category":...}' }] }
  const claudeText = data.content?.[0]?.text ?? data.text ?? null;
  if (claudeText) {
    extracted = JSON.parse(claudeText);
  }
} catch (err) {
  return [{ json: { ...data, _valid: false, _reason: `JSON parse error: ${err.message}`, _rawClaude: data.content?.[0]?.text } }];
}

if (!extracted) {
  return [{ json: { ...data, _valid: false, _reason: 'No extraction from Claude — check Claude Extract node' } }];
}

// Minimum required fields
const required = ['category', 'nominal'];
const missing  = required.filter(k => extracted[k] == null);
if (missing.length > 0) {
  return [{ json: { ...data, _valid: false, _reason: `Missing fields: ${missing.join(', ')}`, extractedData: extracted } }];
}

// Valid categories per Supabase schema
const validCategories = ['pemasukan','pengeluaran','hutang','piutang','bayar_hutang','terima_piutang','unclear'];
if (!validCategories.includes(extracted.category)) {
  extracted.category = 'unclear';
}

return [{ json: { ...data, extractedData: extracted, _valid: true } }];

// Build human-readable confirmation message in Bahasa Indonesia
const data = $input.first().json;
const ext  = data.extractedData;

if (!ext || !data._valid) {
  // Ask for clarification
  return [{
    json: {
      ...data,
      replyText: `Maaf kak, saya kurang paham maksudnya 🙏\nBisa dijelaskan lebih detail?\nContoh: "jual 350rb" atau "beli gula 25rb"`,
    }
  }];
}

// Format nominal
const nominal = Number(ext.nominal ?? 0).toLocaleString('id-ID');

// Category-specific messages
const messages = {
  pemasukan:      `✅ Dicatat! Pemasukan Rp ${nominal}${ext.item ? ` (${ext.item})` : ''} sudah masuk ke buku ya kak 📒`,
  pengeluaran:    `✅ Dicatat! Pengeluaran Rp ${nominal}${ext.item ? ` untuk ${ext.item}` : ''} sudah masuk ke buku 📒`,
  hutang:         `✅ Dicatat! Hutang Rp ${nominal}${ext.pihak ? ` ke ${ext.pihak}` : ''}${ext.jatuh_tempo ? ` (jatuh tempo: ${ext.jatuh_tempo})` : ''} sudah masuk 📒`,
  piutang:        `✅ Dicatat! Piutang Rp ${nominal}${ext.pihak ? ` dari ${ext.pihak}` : ''}${ext.jatuh_tempo ? ` (jatuh tempo: ${ext.jatuh_tempo})` : ''} sudah masuk 📒`,
  bayar_hutang:   `✅ Dicatat! Bayar hutang Rp ${nominal}${ext.pihak ? ` ke ${ext.pihak}` : ''} sudah masuk 📒`,
  terima_piutang: `✅ Dicatat! Terima piutang Rp ${nominal}${ext.pihak ? ` dari ${ext.pihak}` : ''} sudah masuk 📒`,
  unclear:        `🤔 Hmm, saya kurang yakin nih kak. Ini pemasukan atau pengeluaran?\nNominalnya Rp ${nominal}${ext.pihak ? ` (${ext.pihak})` : ''}.`,
};

const replyText = messages[ext.category] ?? messages.unclear;

return [{ json: { ...data, replyText, to: data.senderPhone } }];

